function Factors(N: integer): List<integer>;
begin
  var lst := new List<integer>;
  if N = 1 then
    lst.Add(N);
  var i := 2;
  while i * i <= N do
  begin
    while N.Divs(i) do
    begin
      lst.Add(i);
      N := N div i;
    end;
    i += 1;
  end;
  if N >= 2 then
    lst.Add(N);
  Result := lst;
end;

