function Factors(n: integer): set of integer;
begin
  Result := SetOf(1, n);
  var i := 2;
  while True do
  begin
    var j := n div i;
    if j < i then
      break;
    if i * j = n then
      Result += SetOf(i,j);
    i += 1;
  end;
end;

