const maxcalc = 100000000;

var cache := new integer[maxcalc];

function Fusc(n: integer): integer;
begin
  if (n = 0) or (n = 1) then 
  begin
    Result := n;
    exit
  end;
  if (n < maxcalc) and (cache[n] > 0) then
  begin
    Result := cache[n];
    exit;
  end;
  if n.IsEven then
    Result := Fusc(n div 2)
  else Result := Fusc((n-1) div 2) + Fusc((n+1) div 2);
  if n < maxcalc then
    cache[n] := Result
end;

