function ToBase(number: int64; base: integer): string;
begin
  var sb := new System.Text.StringBuilder('');
  while number > 0 do 
  begin
    sb.Insert(0, valid_chars[integer(number mod base) + 1]);
    number := number div base
  end;
  Result := if sb.Length = 0 then '0'
    else sb.ToString
