function Wrap(words: sequence of string; lineWidth: integer): sequence of string;
begin
  var currentWidth := 0;
  foreach var word in words do
  begin
    if currentWidth <> 0 then
      if currentWidth + word.Length < lineWidth then
      begin
        currentWidth += 1;
        yield ' ';
      end
      else
      begin
        currentWidth := 0;
        yield NewLine;
      end;
    currentWidth += word.Length;
    yield word;
  end;
end;

